<?php
register_shutdown_function(static function():void{if(!class_exists('CompanyProjectGanttSchema',false)||!isset($GLOBALS['db'],$GLOBALS['p'])||!preg_match('/^essential_[a-f0-9]{10}_$/D',$GLOBALS['p']))return;foreach(array_reverse(array_keys(CompanyProjectGanttSchema::definitions($GLOBALS['p']))) as $suffix){unset($GLOBALS['db']->data_cache['table_names']);if($GLOBALS['db']->table_exists($GLOBALS['p'].$suffix))$GLOBALS['db']->query('DROP TABLE '.$GLOBALS['p'].$suffix);}});
require __DIR__.'/project_timesheets_setup.php';require_once APPPATH.'services/CompanyProjectGantt.php';require_once APPPATH.'services/CompanyPortalProjectGantt.php';
if($db->driver()==='mysql'){CompanyProjectGanttSchema::ensure($db,$p);CompanyProjectGanttSchema::ensure($db,$p);}else foreach(CompanyProjectGanttSchema::definitions($p) as $table=>$parts)if(!$db->table_exists($p.$table))$db->query('CREATE TABLE '.$p.$table.'('.implode(',',$parts).')');
$ganttStaff=new CompanyProjectGantt($db,$p);$ganttPortal=new CompanyPortalProjectGantt($db,$p,str_repeat('synthetic-',4));
$ganttSave=function($owner,$flag,$feature,$tag)use($ganttStaff,$portalParents,$key){$s=$ganttStaff->get($owner,7,$portalParents['projects'][$owner]);$ganttStaff->save($owner,7,$portalParents['projects'][$owner],$s['project']['revision'],$s['rules']['revision'],['view_gantt'=>$flag],['project_gantt'=>$feature],$key($tag));};
$ganttDate=function($owner,$task,$start,$visible,$tag)use($ganttStaff,$portalParents,$key){$s=$ganttStaff->get($owner,7,$portalParents['projects'][$owner],$task);$ganttStaff->taskDate($owner,7,$portalParents['projects'][$owner],$s['project']['revision'],$task,$s['task']['revision'],$s['dates']['revision']??0,$start,$visible,$key($tag));};
